def file(path):
    path = secure_filename(path)
    if app.interface.encrypt and isinstance(app.interface.examples, str) and path.startswith(app.interface.examples):
        with open(os.path.join(app.cwd, path), "rb") as encrypted_file:
            encrypted_data = encrypted_file.read()
        file_data = encryptor.decrypt(
            app.interface.encryption_key, encrypted_data)
        return send_file(io.BytesIO(file_data), attachment_filename=os.path.basename(path))
    else:
        return send_file(os.path.join(app.cwd, path))

def handle_get(self) -> bool:
    if self.do_log:
        logmsg = "%-4s %s @%s" % (self.mode, self.req, self.uname)

        if "range" in self.headers:
            try:
                rval = self.headers["range"].split("=", 1)[1]
            except:
                rval = self.headers["range"]

            logmsg += " [\033[36m" + rval + "\033[0m]"

        self.log(logmsg)

    # "embedded" resources
    if self.vpath.startswith(".cpr"):
        if self.vpath.startswith(".cpr/ico/"):
            return self.tx_ico(self.vpath.split("/")[-1], exact=True)

        if self.vpath.startswith(".cpr/ssdp"):
            return self.conn.hsrv.ssdp.reply(self)

        if self.vpath.startswith(".cpr/dd/") and self.args.mpmc:
            if self.args.mpmc == ".":
                raise Pebkac(404)

            loc = self.args.mpmc.rstrip("/") + self.vpath[self.vpath.rfind("/") :]
            h = {"Location": loc, "Cache-Control": "max-age=39"}
