def dataReceived(self, data: bytes) -> None:
    self.stream.write(data)
    self.length += len(data)
    if self.max_size is not None and self.length >= self.max_size:
        self.deferred.errback(
            SynapseError(
                502,
                "Requested file is too large > %r bytes" % (self.max_size,),
                Codes.TOO_LARGE,
            )
        )
        self.deferred = defer.Deferred()
        self.transport.loseConnection()

def parse_osc_99(raw: str) -> NotificationCommand:
    cmd = NotificationCommand()
    metadata, payload = raw.partition(';')[::2]
    payload_is_encoded = False
    payload_type = 'title'
    if metadata:
        for part in metadata.split(':'):
            try:
                k, v = part.split('=', 1)
            except Exception:
                log_error('Malformed OSC 99: metadata is not key=value pairs')
                return cmd
            if k == 'p':
                payload_type = v
            elif k == 'i':
                cmd.identifier = v
            elif k == 'e':
                payload_is_encoded = v == '1'
            elif k == 'd':
                cmd.done = v != '0'
            elif k == 'a':
                cmd.actions += f',{v}'
    if payload_type not in ('body', 'title'):
        log_error(f'Malformed OSC 99: unknown payload type: {payload_type}')
        return NotificationCommand()
    if payload_is_encoded:
        try:
            payload = standard_b64decode(payload).decode('utf-8')
        except Exception:
            log_error('Malformed OSC 99: payload is not base64 encoded UTF-8 text')
            return NotificationCommand()
    if payload_type == 'title':
        cmd.title = payload
    else:
        cmd.body = payload
    return cmd

def should_run(self):
    if self.force:
        return True
    if not os.path.exists(self.bower_dir):
        return True

    return mtime(self.bower_dir) < mtime(pjoin(repo_root, 'bower.json'))

def on_end(self) -> None:
    message = (MultiPartMessage.END, b"")
    self.messages.append(message)

def dbLookup(msg):
    if len(msg.split(',')) != 2:
        #procura na lista de paises
        query = 'SELECT id FROM paises WHERE nome == "%s"' % (msg)
        cursor.execute(query)
        if cursor.fetchone():
            return True
        else:
            return False
    else:
        cidade = msg.split(',')[0].strip()
        estado = msg.split(',')[1].strip()
        #check cidade pertence ao estado
        query = 'SELECT estados.id FROM municipios JOIN estados ON municipios.estados_id == estados.id WHERE municipios.nome == "%s" AND estados.uf == "%s";' % (cidade, estado)
        cursor.execute(query)
        if not cursor.fetchone():
            return False

    return True

def on_header_field(self, data: bytes, start: int, end: int) -> None:
    message = (MultiPartMessage.HEADER_FIELD, data[start:end])
    self.messages.append(message)
